<?php
function workbookRows(string $path,string $name):array{
 $ext=strtolower(pathinfo($name,PATHINFO_EXTENSION));attRequire(in_array($ext,['csv','xlsx','xls']), 'Use CSV, XLSX or XLS.');
 if($ext==='csv')return readSheet($path,$name);
 if($ext==='xlsx'){$z=new ZipArchive();attRequire($z->open($path)===true,'Invalid XLSX.');$size=0;for($i=0;$i<$z->numFiles;$i++)$size+=$z->statIndex($i)['size'];$z->close();attRequire($size<=40*1024*1024,'Workbook is too large.');}
 $reader=\PhpOffice\PhpSpreadsheet\IOFactory::createReader($ext==='xls'?'Xls':'Xlsx');attRequire($reader->canRead($path),'File content does not match its extension.');
 $info=$reader->listWorksheetInfo($path);attRequire(!empty($info)&&$info[0]['totalRows']<=5001&&$info[0]['totalColumns']<=40,'Use at most 5,000 rows and 40 columns in the first sheet.');$reader->setLoadSheetsOnly($info[0]['worksheetName']);$book=$reader->load($path);$sheet=$book->getSheet(0);$rows=[];$headers=[];
 for($r=1;$r<=$info[0]['totalRows'];$r++){$row=[];for($c=1;$c<=$info[0]['totalColumns'];$c++){$cell=$sheet->getCell([$c,$r]);attRequire($cell->getDataType()!=='f','Replace formulas with values before uploading.');$v=$cell->getValue();if($v instanceof \PhpOffice\PhpSpreadsheet\RichText\RichText)$v=$v->getPlainText();if($r>1&&is_numeric($v)&&in_array($headers[$c-1]??'',['Date','Class Date','Valid From','Valid Until','Start Time','End Time'])){$dt=\PhpOffice\PhpSpreadsheet\Shared\Date::excelToDateTimeObject((float)$v);$v=$dt->format(str_contains($headers[$c-1],'Time')?'H:i':'Y-m-d');}$row[]=trim((string)$v);}if($r===1)$headers=$row;$rows[]=$row;}$book->disconnectWorksheets();return $rows;
}
function attHeaders():array{return ['Academic Year','Semester','Department','Programme','Year','Section','Subject Code','Subject Name','Tutor Email','Tutor Name','Day','Class Date','Start Time','End Time','Classroom','Valid From','Valid Until','Combined Session ID','Student Count','Delivery Mode','Attendance Required','Flexible'];}
function dayNumber(string $day):int{$days=['monday','tuesday','wednesday','thursday','friday','saturday','sunday'];$index=array_search(strtolower(trim($day)),$days,true);attRequire($index!==false,'Use a full weekday name (Monday–Sunday).');return $index+1;}
function normalizeSchedule(array $r,string $from,string $until):array{
 $mode=trim($r['Delivery Mode']??'')?:'In person';$required=trim($r['Attendance Required']??'')?:'Yes';$flex=trim($r['Flexible']??'')?:'No';attRequire(in_array($mode,['In person','Online'])&&in_array($required,['Yes','No'])&&in_array($flex,['Yes','No']),'Use In person/Online and Yes/No for attendance and flexibility.');attRequire($mode!=='Online'||$required==='No','Online sessions require Attendance Required = No; classroom QR is unavailable online.');
 $r['Year']=['I'=>'1','II'=>'2','III'=>'3','IV'=>'4'][$r['Year']??'']??($r['Year']??'');
 foreach(['Academic Year','Semester','Department','Programme','Year','Section','Subject Code','Subject Name','Tutor Email','Day','Start Time','End Time']as $key)attRequire(trim($r[$key]??'')!=='','Missing '.$key.'.');
 $staff=one('SELECT * FROM users WHERE LOWER(email)=? AND active=1',[strtolower(trim($r['Tutor Email']))]);attRequire($staff&&teaching($staff),'Tutor email not found or attendance permission is not enabled.');
 attRequire(in_array($r['Department'],departments(),true),'Unknown department.');attRequire(in_array($r['Programme'],programmes(),true),'Unknown programme.');$room=one('SELECT id FROM classrooms WHERE room_code=? AND active=1',[$r['Classroom']??'']);attRequire($mode==='Online'||(bool)$room,'Classroom not found or inactive.');
 $date=trim($r['Class Date']??'');$weekday=dayNumber($r['Day']);attRequire(!$date||(dateValid($date)&&(int)date('N',strtotime($date))===$weekday),'Class Date must match Day.');
 $from=trim($r['Valid From']??'')?:$from;$until=trim($r['Valid Until']??'')?:$until;if($date){$from=$date;$until=$date;}attRequire(dateValid($from)&&dateValid($until)&&$until>=$from&&(strtotime($until)-strtotime($from))<=366*86400,'Supply valid term dates, at most one year apart.');
 attRequire(timeValid($r['Start Time'])&&timeValid($r['End Time'])&&$r['End Time']>$r['Start Time'],'Invalid start/end time.');attRequire(ctype_digit((string)$r['Year'])&&(int)$r['Year']>=1&&(int)$r['Year']<=4,'Year must be I, II, III or IV (or 1–4).' );
 foreach(['Academic Year'=>40,'Semester'=>40,'Section'=>40,'Subject Code'=>60,'Subject Name'=>160]as $key=>$max)attRequire(mb_strlen($r[$key])<=$max,$key.' is too long.');
 $groups=normalizeParticipantGroups($r);$count=trim((string)($r['Student Count']??''));attRequire($count===''||(ctype_digit($count)&&(int)$count>0&&(int)$count<=10000),'Student Count must be a positive whole number.');
 return ['delivery_mode'=>$mode,'attendance_required'=>$required==='Yes'?1:0,'flexible'=>$flex==='Yes'?1:0,'participant_groups'=>json_encode($groups),'student_count'=>$count===''?null:(int)$count,'academic_year'=>$r['Academic Year'],'semester'=>$r['Semester'],'department'=>$r['Department'],'programme'=>$r['Programme'],'year_level'=>(int)$r['Year'],'section'=>$r['Section'],'subject_code'=>$r['Subject Code'],'subject_name'=>$r['Subject Name'],'staff_id'=>(int)$staff['id'],'weekday'=>$weekday,'class_date'=>$date?:null,'start_time'=>$r['Start Time'],'end_time'=>$r['End Time'],'classroom_id'=>$mode==='Online'?0:(int)$room['id'],'valid_from'=>$from,'valid_until'=>$until,'active'=>1];
}
function sameOccurrence(array $a,array $b):bool{
 $from=max($a['valid_from'],$b['valid_from']);$until=min($a['valid_until'],$b['valid_until']);if($from>$until||$a['weekday']!=$b['weekday'])return false;
 if(!empty($a['class_date']))return occurs($b,$a['class_date']);if(!empty($b['class_date']))return occurs($a,$b['class_date']);$delta=((int)$a['weekday']-(int)date('N',strtotime($from))+7)%7;return date('Y-m-d',strtotime($from." +$delta days"))<=$until;
}
function scheduleConflict(array $t,array $others,int $ignore=0):?string{
 foreach($others as $o){if($ignore&&(int)($o['id']??0)===$ignore)continue;if(!$o['active'])continue;if(!sameOccurrence($t,$o)||$t['start_time']>=$o['end_time']||$t['end_time']<=$o['start_time'])continue;
 if($t['staff_id']==$o['staff_id'])return 'Tutor has an overlapping class (or duplicate row). '.conflictDescription($o);if(($t['delivery_mode']??'In person')!=='Online'&&($o['delivery_mode']??'In person')!=='Online'&&$t['classroom_id']==$o['classroom_id'])return 'Classroom already occupied. '.conflictDescription($o);
 }return null;
}
function timetablePreview(array $rows,string $from,string $until):array{
 $headers=array_map(fn($v)=>trim(ltrim((string)$v,"\xEF\xBB\xBF")),array_shift($rows)??[]);attRequire(count($headers)===count(array_unique($headers)),'Duplicate column headers.');foreach(array_diff(attHeaders(),['Tutor Name','Class Date','Valid From','Valid Until','Combined Session ID','Student Count','Delivery Mode','Attendance Required','Flexible'])as $h)attRequire(in_array($h,$headers,true),'Missing column: '.$h);
 $others=all('SELECT * FROM tutor_timetable WHERE active=1');$preview=[];$batches=[];
 foreach($rows as $i=>$row){if(!array_filter($row,fn($v)=>trim((string)$v)!==''))continue;$r=array_combine($headers,array_slice(array_pad($row,count($headers),''),0,count($headers)));$key=trim($r['Combined Session ID']??'');$batches[$key!==''?'combined:'.$key:'row:'.$i][]=['row'=>$i+2,'source'=>$r];}
 foreach($batches as $batch){$r=$batch[0]['source'];$item=['row'=>implode(', ',array_column($batch,'row')),'source'=>$r,'sources'=>$batch,'status'=>'Valid','message'=>'','data'=>null];try{
 $groups=[];foreach($batch as $entry){$other=$entry['source'];foreach($headers as $h)if(!in_array($h,['Department','Programme','Year','Section','Tutor Name','Original Row','Import Error'],true))attRequire(($r[$h]??'')===($other[$h]??''),'Combined Session ID must have identical tutor, module, day/date, time, room, term and student count. Use different IDs for different sessions.');$groups[]=normalizeParticipantGroups($other)[0];}
 $r['Participant Groups']=$groups;$item['source']=$r;$t=normalizeSchedule($r,$from,$until);$conflict=scheduleConflict($t,$others);attRequire(!$conflict,$conflict??'');$item['data']=$t;$t['_source_rows']=$item['row'];$item['message']=count($groups)>1?count($groups).' participating groups; one attendance session.':'';$others[]=$t;
 }catch(RuntimeException $e){$item['status']='Error';$item['message']=$e->getMessage();}$preview[]=$item;}attRequire((bool)$preview,'No timetable rows found.');return $preview;
}
function normalizeParticipantGroups(array $r):array{
 $groups=$r['Participant Groups']??[['department'=>$r['Department']??'','programme'=>$r['Programme']??'','year_level'=>$r['Year']??'','section'=>$r['Section']??'']];$result=[];
 foreach($groups as $g){$year=['I'=>1,'II'=>2,'III'=>3,'IV'=>4][$g['year_level']??'']??($g['year_level']??'');attRequire(in_array($g['department']??'',departments(),true),'Unknown participating department.');attRequire(in_array($g['programme']??'',programmes(),true),'Unknown participating programme.');attRequire(in_array((string)$year,['1','2','3','4'],true),'Participating group year must be I–IV.');$section=trim($g['section']??'');attRequire($section!==''&&mb_strlen($section)<=40,'Supply a section for each participating group.');$g=['department'=>$g['department'],'programme'=>$g['programme'],'year_level'=>(int)$year,'section'=>$section];$result[json_encode($g)]=$g;}attRequire(count($result)>0&&count($result)<=50,'Use 1–50 participating groups.');return array_values($result);
}
function sessionGroups(array $t):array{return !empty($t['participant_groups'])?(json_decode($t['participant_groups'],true)?:[]):[['department'=>$t['department'],'programme'=>$t['programme'],'year_level'=>$t['year_level'],'section'=>$t['section']]];}
function sessionMatches(array $t,string $key,string $value):bool{if(in_array($key,['department','programme','year_level','section'],true)){foreach(sessionGroups($t)as $g)if((string)$g[$key]===$value)return true;return false;}return (string)($t[$key]??'')===$value;}
function sessionLabel(array $t,string $key):string{return implode('; ',array_unique(array_column(sessionGroups($t),$key)));}

function insertSchedule(array $t,int $actor):int{$cols=array_keys($t);q('INSERT INTO tutor_timetable('.implode(',',$cols).',created_by,created_at,updated_at) VALUES('.implode(',',array_fill(0,count($cols)+3,'?')).')',[...array_values($t),$actor,now(),now()]);return (int)db()->lastInsertId();}
function timetableCommit(array $preview,array $u):int{attRequire(academic($u));attLock();$others=all('SELECT * FROM tutor_timetable WHERE active=1');$count=0;foreach($preview as $item){if($item['status']!=='Valid')continue;$old=$item['data'];$t=normalizeSchedule($item['source'],$old['valid_from'],$old['valid_until']);$conflict=scheduleConflict($t,$others);attRequire(!$conflict,'Timetable changed since preview. Upload again. '.($conflict??''));$id=insertSchedule($t,(int)$u['id']);$others[]=$t;attAudit((int)$u['id'],'Timetable uploaded',$id);$count++;}return $count;}
function excelDownload(array $headers,array $rows,string $name):never{$book=new \PhpOffice\PhpSpreadsheet\Spreadsheet();$sheet=$book->getActiveSheet();foreach([$headers,...$rows]as $ri=>$row)foreach(array_values($row)as $ci=>$value)$sheet->setCellValueExplicit([$ci+1,$ri+1],(string)($value??''),\PhpOffice\PhpSpreadsheet\Cell\DataType::TYPE_STRING);$sheet->freezePane('A2');foreach(range(1,count($headers))as $c)$sheet->getColumnDimension(\PhpOffice\PhpSpreadsheet\Cell\Coordinate::stringFromColumnIndex($c))->setWidth(24);header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="'.$name.'.xlsx"');(new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($book))->save('php://output');exit;}

function conflictDescription(array $t):string{return 'Conflicts with '.(!empty($t['id'])?'saved timetable #'.$t['id']:'upload row(s) '.($t['_source_rows']??'earlier in this file')).': '.$t['subject_code'].' / '.$t['department'].' / '.($t['class_date']?:['','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][$t['weekday']]).' '.$t['start_time'].'–'.$t['end_time'].' ('.$t['valid_from'].' to '.$t['valid_until'].').';}
function savedImportResult():array{if(empty($_GET['batch']))return []; $r=one('SELECT results FROM timetable_import_results WHERE id=?',[(string)$_GET['batch']]);return $r?(json_decode($r['results'],true)?:[]):[];}
function importCorrectionRows(array $items):array{$rows=[];foreach($items as $item)if(in_array($item['status'],['Error','Not uploaded'],true))foreach($item['sources']??[['row'=>$item['row'],'source'=>$item['source']]]as $entry){$source=$entry['source'];$rows[]=[...array_map(fn($h)=>$source[$h]??'',attHeaders()),$entry['row'],$item['message']];}return $rows;}
function rescheduleOwnSession(array $u,array $p):void{
 attRequire(teaching($u));attLock();$t=one('SELECT * FROM tutor_timetable WHERE id=?',[(int)($p['id']??0)]);attRequire($t&&$t['active']&&!empty($t['flexible'])&&(int)$t['staff_id']===(int)$u['id'],'Only your own enabled flexible sessions can be changed.');attRequire(!empty($t['class_date'])&&strtotime($t['class_date'].' '.$t['start_time'])>time(),'Only future specific-date sessions can be rescheduled. Ask DAA to replace recurring schedules.');attRequire(!one('SELECT id FROM tutor_attendance WHERE timetable_id=?',[$t['id']]),'Recorded attendance cannot be changed.');$old=$t;$date=required($p,'class_date');$a=required($p,'start_time');$b=required($p,'end_time');attRequire(dateValid($date)&&timeValid($a)&&timeValid($b)&&$b>$a&&strtotime($date.' '.$a)>time(),'Choose a future date and valid start/end times.');attRequire((bool)one('SELECT id FROM teaching_calendars WHERE active=1 AND academic_year=? AND semester=? AND valid_from<=? AND valid_until>=?',[$t['academic_year'],$t['semester'],$date,$date]),'Date must be within the active college calendar.');$room=0;if($t['delivery_mode']!=='Online'){$r=one('SELECT id FROM classrooms WHERE id=? AND active=1',[(int)($p['classroom_id']??0)]);attRequire((bool)$r,'Choose an active classroom.');$room=(int)$r['id'];}$t=array_merge($t,['class_date'=>$date,'weekday'=>(int)date('N',strtotime($date)),'valid_from'=>$date,'valid_until'=>$date,'start_time'=>$a,'end_time'=>$b,'classroom_id'=>$room]);$conflict=scheduleConflict($t,all('SELECT * FROM tutor_timetable WHERE active=1'),(int)$t['id']);attRequire(!$conflict,$conflict??'');q('UPDATE tutor_timetable SET class_date=?,weekday=?,valid_from=?,valid_until=?,start_time=?,end_time=?,classroom_id=?,updated_at=? WHERE id=?',[$date,$t['weekday'],$date,$date,$a,$b,$room,now(),$t['id']]);attAudit((int)$u['id'],'Tutor rescheduled flexible session',(int)$t['id'],['before'=>$old,'after'=>$t]);
}
